"""Static paper-only snapshot of hourly strategies, linked to their source."""
import argparse,html,json,hashlib
from datetime import datetime,timezone
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--source',required=True);a=p.parse_args();src=Path(a.source).resolve();repo=Path(__file__).resolve().parent.parent;out=repo/'experimentos/daytrade';out.mkdir(parents=True,exist_ok=True)
read=lambda f:json.loads((src/f).read_text());h=read('web/data/daytrade-integrated-history.json');f=read('web/data/daytrade-integrated-forward.json');e=html.escape
