data={'snapshotAt':datetime.now(timezone.utc).isoformat(),'mode':'static_paper_only','historical':{**h,'results':[compact(r) for r in h['results']]},'forward':{**f,'arms':[{**{k:v for k,v in a.items() if k not in ['scenarios','decisions']},'scenarios':[compact(r) for r in a['scenarios']]}for a in f.get('arms',[])]},'testsPassed':232,'codeManifestSHA256':hashlib.sha256((repo/'app/source-manifest.json').read_bytes()).hexdigest()};(out/'snapshot.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
rows=''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>'for v in[r['symbol'],r['label'],r['variant'],r['cost'],f"R$ {r['pnlBRL']:.2f}",r['count'],f"{r['maxDD']*100:.2f}%",f"{r['avgHoldHours']:.1f}h" if r['avgHoldHours'] is not None else '—'])+'</tr>'for r in h['results'])
